int i, iso_count = 0, outlier_count = 0;
adcs_vec3_t v[3];
adcs_vec3_t med;
double d2[3];
int invalid = 0;

gv_output.mode = GV_FAULT;
gv_output.voted_rate_rad_s.x = 0.0;
gv_output.voted_rate_rad_s.y = 0.0;
gv_output.voted_rate_rad_s.z = 0.0;
gv_output.distance_rad_s[0] = 0.0;
gv_output.distance_rad_s[1] = 0.0;
gv_output.distance_rad_s[2] = 0.0;
gv_output.outlier_mask = 0U;

if ((gv_input.enable != 0) && (gv_input.enable != 1))
    invalid = 1;
for (i = 0; i < 3; i++) {
    if (gv_input.gyro[i] == NULL)
        invalid = 1;
    else if (!adcs_is_finite_vec3(gv_input.gyro[i]))
        invalid = 1;
}
if ((!isfinite(gv_config.threshold_rad_s)) || (gv_config.threshold_rad_s < 0.0))
    invalid = 1;
if ((!isfinite(gv_config.reentry_threshold_rad_s)) ||
    (gv_config.reentry_threshold_rad_s < 0.0) ||
    (gv_config.reentry_threshold_rad_s > gv_config.threshold_rad_s))
    invalid = 1;
if ((gv_config.isolate_confirm < 1U) || (gv_config.isolate_confirm > 20U))
    invalid = 1;
if ((gv_config.reentry_confirm < 1U) || (gv_config.reentry_confirm > 20U))
    invalid = 1;

if (invalid) {
    for (i = 0; i < 3; i++) {
        gv_state.isolated[i] = 0;
        gv_state.bad_streak[i] = 0U;
        gv_state.good_streak[i] = 0U;
    }
    gv_state.mode = GV_FAULT;
    gv_output.mode = GV_FAULT;
    return;
}

for (i = 0; i < 3; i++)
    v[i] = *(gv_input.gyro[i]);

med.x = v[0].x + v[1].x + v[2].x - fmin(v[0].x, fmin(v[1].x, v[2].x)) -
        fmax(v[0].x, fmax(v[1].x, v[2].x));
med.y = v[0].y + v[1].y + v[2].y - fmin(v[0].y, fmin(v[1].y, v[2].y)) -
        fmax(v[0].y, fmax(v[1].y, v[2].y));
med.z = v[0].z + v[1].z + v[2].z - fmin(v[0].z, fmin(v[1].z, v[2].z)) -
        fmax(v[0].z, fmax(v[1].z, v[2].z));

for (i = 0; i < 3; i++) {
    d2[i] = (v[i].x - med.x) * (v[i].x - med.x) +
            (v[i].y - med.y) * (v[i].y - med.y) +
            (v[i].z - med.z) * (v[i].z - med.z);
    gv_output.distance_rad_s[i] = sqrt(d2[i]);
    if (gv_output.distance_rad_s[i] > gv_config.threshold_rad_s)
        gv_output.outlier_mask |= (unint32)(1U << i);
}

if (gv_input.enable == 0) {
    for (i = 0; i < 3; i++) {
        gv_state.isolated[i] = 0;
        gv_state.bad_streak[i] = 0U;
        gv_state.good_streak[i] = 0U;
    }
    gv_state.mode = GV_OFF;
    gv_output.mode = GV_OFF;
    return;
}

for (i = 0; i < 3; i++) {
    if (!gv_state.isolated[i]) {
        if (gv_output.outlier_mask & (unint32)(1U << i)) {
            gv_state.bad_streak[i]++;
            if (gv_state.bad_streak[i] >= gv_config.isolate_confirm) {
                gv_state.isolated[i] = 1;
                gv_state.bad_streak[i] = 0U;
                gv_state.good_streak[i] = 0U;
            }
        } else {
            gv_state.bad_streak[i] = 0U;
        }
    } else {
        if (!(gv_output.outlier_mask & (unint32)(1U << i))) {
            gv_state.good_streak[i]++;
            if (gv_state.good_streak[i] >= gv_config.reentry_confirm) {
                gv_state.isolated[i] = 0;
                gv_state.bad_streak[i] = 0U;
                gv_state.good_streak[i] = 0U;
            }
        } else {
            gv_state.good_streak[i] = 0U;
        }
    }
}

for (i = 0; i < 3; i++) {
    if (gv_output.outlier_mask & (unint32)(1U << i))
        outlier_count++;
    if (gv_state.isolated[i])
        iso_count++;
}

if (iso_count >= 2) {
    gv_state.mode = GV_FAULT;
    gv_output.mode = GV_FAULT;
} else if (iso_count == 1) {
    int a = -1, b = -1;
    for (i = 0; i < 3; i++) {
        if (!gv_state.isolated[i]) {
            if (a < 0)
                a = i;
            else
                b = i;
        }
    }
    if ((a >= 0) && (b >= 0)) {
        double dx = v[a].x - v[b].x;
        double dy = v[a].y - v[b].y;
        double dz = v[a].z - v[b].z;
        double dm = sqrt(dx * dx + dy * dy + dz * dz);
        if (dm <= gv_config.threshold_rad_s) {
            gv_output.voted_rate_rad_s.x = 0.5 * (v[a].x + v[b].x);
            gv_output.voted_rate_rad_s.y = 0.5 * (v[a].y + v[b].y);
            gv_output.voted_rate_rad_s.z = 0.5 * (v[a].z + v[b].z);
            gv_state.mode = GV_DEGRADED;
            gv_output.mode = GV_DEGRADED;
        } else {
            gv_state.mode = GV_FAULT;
            gv_output.mode = GV_FAULT;
        }
    } else {
        gv_state.mode = GV_FAULT;
        gv_output.mode = GV_FAULT;
    }
} else {
    if (outlier_count == 0) {
        gv_output.voted_rate_rad_s = med;
        gv_state.mode = GV_NOMINAL;
        gv_output.mode = GV_NOMINAL;
    } else if (outlier_count == 1) {
        int a = -1, b = -1;
        for (i = 0; i < 3; i++) {
            if (!(gv_output.outlier_mask & (unint32)(1U << i))) {
                if (a < 0)
                    a = i;
                else
                    b = i;
            }
        }
        if ((a >= 0) && (b >= 0)) {
            gv_output.voted_rate_rad_s.x = 0.5 * (v[a].x + v[b].x);
            gv_output.voted_rate_rad_s.y = 0.5 * (v[a].y + v[b].y);
            gv_output.voted_rate_rad_s.z = 0.5 * (v[a].z + v[b].z);
            gv_state.mode = GV_DEGRADED;
            gv_output.mode = GV_DEGRADED;
        } else {
            gv_state.mode = GV_FAULT;
            gv_output.mode = GV_FAULT;
        }
    } else {
        gv_state.mode = GV_FAULT;
        gv_output.mode = GV_FAULT;
    }
}

